    desc: '蘇格蘭東岸的公眾林克斯，16 世紀就有人在這片沙地打球。球場由 Allan Robertson 起步、老湯姆莫里斯（Old Tom Morris）擴成 18 洞，1926 年 James Braid 改造成今天的冠軍球場。這裡舉辦過 8 屆英國公開賽：1953 年 Ben Hogan 這輩子只參加過一次英國公開賽就在這裡奪冠，第 6 洞因此叫「Hogan\'s Alley」；Tom Watson 1975 年在這裡拿下第一座公開賽；1999 年法國選手 Jean van de Velde 最後一洞領先三桿，卻在第 18 洞打進 Barry Burn 小溪吃下三柏忌，把冠軍送給 Paul Lawrie，是高爾夫史上最有名的崩盤。蜿蜒的 Barry Burn 在最後兩洞來回橫越球道好幾次，加上強勁海風，讓它得到「Carnasty（可惡的卡努斯蒂）」的外號，公認是公開賽輪值球場裡最難的一座。每洞形狀照官網的 Strokesaver 球道圖。',
