// 分區球場（例如長庚北 / 中 / 南）：base.holes 先放全部 27 洞，選區後用「代號:前九後九」組成 18 洞（例如 cggc:NM）
for (const c of COURSES) if (c.nines) c.holes = c.nines.flatMap(n => n.holes);
const combos = new Map();
export function nineCombo(base, f, b) { return `${base.id}:${f}${b || ''}`; }
// 挑戰模式的關卡（不列在球場選單裡）
const EXTRA = new Map();
export function registerCourse(c) { EXTRA.set(c.id, c); }
export function courseById(id) {
  if (EXTRA.has(id)) return EXTRA.get(id);
  const direct = COURSES.find(c => c.id === id);
  if (direct) return direct.nines ? courseById(nineCombo(direct, direct.nines[0].id, direct.nines[1].id)) : direct;
  if (combos.has(id)) return combos.get(id);
  const [bid, code = ''] = String(id).split(':');
  const base = COURSES.find(c => c.id === bid);
  if (!base || !base.nines) return COURSES[0];
  const pick = [...code].map(k => base.nines.find(n => n.id === k)).filter(Boolean);
  if (!pick.length) pick.push(base.nines[0]);
  if (pick.length < 2) pick.push(base.nines.find(n => n !== pick[0]));
  // 18 洞的差點：前九換成單數（1,3,…17）、後九換成雙數（2,4,…18）
  const holes = pick.flatMap((n, k) => n.holes.map(h => { const x = h.slice(); x[4] = h[4] * 2 - (k === 0 ? 1 : 0); return x; }));
  const c = {
    ...base, id: `${bid}:${pick[0].id}${pick[1].id}`, baseId: bid, nineIds: pick.map(n => n.id), nineNames: pick.map(n => n.name),
    name: `${base.name}（${pick[0].name}＋${pick[1].name}）`, holes, maps: null, _mapsP: null, mapsUrl: null,
  };
  combos.set(id, c);
  if (c.id !== id) combos.set(c.id, c);
  return c;
}
// 分區球場某一洞的名稱（例如「北區 3」）
export function holeLabel(course, idx) {
  return course.nineNames ? `${course.nineNames[Math.floor(idx / 9)]} ${idx % 9 + 1}` : '';
}

// 真實球場的描圖地圖：第一次用到時下載（之後從手機快取讀），建洞之前要先等它
// 自製球場 / 修改過的現有球洞（custom.js 設定）：球場地圖載入後套用（每座球場只套一次）
let mapsHook = null;
export function setMapsHook(fn) { mapsHook = fn; }
export async function loadCourseMaps(course) {
  // 自製球場：地圖從 Google 試算表下載（第一次打才下載，之後從手機快取讀）
  if (course && course.loadMaps) { if (!course.maps) await course.loadMaps(course); return; }
  if (course && course.baseId && !course.maps) {
    // 分區組合：先載入整座球場 27 洞的地圖，再挑出選到的兩區
    const base = COURSES.find(c => c.id === course.baseId);
    await loadCourseMaps(base);
    const order = base.mapsOrder || base.nines.map(n => n.id);
    if (base.maps) course.maps = course.nineIds.flatMap(k => { const i = order.indexOf(k); return base.maps.slice(i * 9, i * 9 + 9); });
    return;
  }
  if (!course || !course.mapsUrl) return;
  // 國外真實球場另外有整座球場共用的場景檔（地形高程、建築、海岸線），每一洞的地圖都指到同一份
  if (!course.maps) {
    if (!course._mapsP) course._mapsP = Promise.all([fetch(course.mapsUrl).then(r => r.json()), course.sceneUrl ? fetch(course.sceneUrl).then(r => r.json()) : null])
      .then(([m, sc]) => { if (sc) for (const h of m) h.scene = sc; course.maps = m; }).catch(e => { course._mapsP = null; throw e; });
    await course._mapsP;
  }
  // 地圖已經下載好、修改過的球洞還在套用時，也要等它套完（不然 18 洞預覽會用到原本的地圖）
  if (mapsHook) await (course._hookP = course._hookP || mapsHook(course).catch(e => { console.warn('修改過的球洞載入失敗', e); }));
}
// 修改 / 還原現有球洞後：這座球場（含分區組合）已經載入的地圖作廢，下次用到時重新載入並套用
export function resetCourseMaps(id) {
  for (const c of [COURSES.find(x => x.id === id), ...[...combos.values()].filter(x => x.baseId === id)]) if (c) { c.maps = null; c._mapsP = null; c._hookP = null; }
}

export function teeYards(course, holeIdx, teeId) {
  const t = TEE_SETS.find(x => x.id === teeId) || TEE_SETS[1];
  const spec = course.holes[holeIdx][5];
  if (spec && spec.tees && spec.tees[t.id]) return spec.tees[t.id];      // 真實球場：用各梯台的實際碼數
  return Math.round(course.holes[holeIdx][1] * t.ratio);
}

export function courseYards(course, teeId) {
  return course.holes.reduce((s, _, i) => s + teeYards(course, i, teeId), 0);
}
